// scripts/src/domain/links.ts
function appleMusicStorefront(url) {
  const m = /^https?:\/\/music\.apple\.com\/([a-z]{2})(?:\/|$)/i.exec(url);
  return m ? m[1].toLowerCase() : "global";
}
function singleAppleMusic(links) {
  const rank = (l) => {
    const s = appleMusicStorefront(l.url);
    return s === "tw" ? 0 : s === "global" ? 1 : 2;
  };
  const apple = links.filter((l) => l.platform === "appleMusic");
  if (apple.length <= 1) return links;
  const best = apple.reduce((a, b) => rank(b) < rank(a) ? b : a);
  return links.filter((l) => l.platform !== "appleMusic" || l === best);
}
var EXTERNAL_ORDER = ["musicBrainz", "wikidata", "wikipedia", "other"];
var orderedExternalLinks = (ls) => EXTERNAL_ORDER.flatMap((p) => ls.filter((l) => l.platform === p));
function externalLinkTitle(l) {
  if (l.platform === "musicBrainz") return "MusicBrainz";
  if (l.platform === "wikidata") return "Wikidata";
  if (l.platform === "wikipedia") return `Wikipedia（${urlHost(l.url)?.split(".")[0] ?? ""}）`;
  return urlHost(l.url) ?? l.url;
}

