// scripts/src/domain/calendar-entry.ts
function calendarEntry(festival2, artists, p, lang2 = "zh", names = lang2) {
  const leads = p.leadArtistIds.map((id) => artistName(artists, id, names)).join(" × ");
  const stage2 = stageNames(festival2, p, lang2) || void 0;
  const feat = p.guestArtistIds.length > 0 ? `ft. ${p.guestArtistIds.map((id) => artistName(artists, id, names)).join(lang2 === "en" ? ", " : "、")}` : "";
  const who = feat ? `${leads} ${feat}` : leads;
  return {
    title: stage2 ? `${who}|${stage2}` : who,
    start: new Date(toEpoch(p.slot.start)),
    end: new Date(toEpoch(p.slot.end)),
    location: festival2.venueName,
    coordinate: { latitude: festival2.map.center.latitude, longitude: festival2.map.center.longitude },
    notes: [pickFestivalName(festival2.name, lang2), stage2 ?? "", feat].filter(Boolean).join("\n"),
    timeZone: "Asia/Taipei"
  };
}
var utcStamp = (d) => d.toISOString().replace(/[-:]/g, "").replace(/\.\d{3}/, "");
var googleCalendarUrl = (e2) => {
  const q = [["text", e2.title], ["location", e2.location], ["details", e2.notes], ["ctz", e2.timeZone]];
  return `https://calendar.google.com/calendar/render?action=TEMPLATE&dates=${utcStamp(e2.start)}/${utcStamp(e2.end)}&` + q.map(([k, v]) => `${k}=${encodeURIComponent(v)}`).join("&");
};
function missingEntries(entries, existing) {
  const have = new Set(existing.map((e2) => `${e2.start}|${e2.title}`));
  return entries.filter((e2) => !have.has(`${e2.start.getTime()}|${e2.title}`));
}

// scripts/src/ui/calendar.ts
function newEvent(e2, calendar) {
  const ev = new CalendarEvent();
  ev.title = e2.title;
  ev.startDate = e2.start;
  ev.endDate = e2.end;
  ev.location = e2.location;
  ev.structuredLocation = { title: e2.location, geoLocation: { latitude: e2.coordinate.latitude, longitude: e2.coordinate.longitude, timestamp: Date.now() }, radius: 0 };
  ev.notes = e2.notes;
  ev.timeZone = e2.timeZone;
  ev.calendar = calendar;
  ev.addAlarm(EventAlarm.fromRelativeOffset(-15 * 60));
  return ev;
}
async function planCalendar(entries) {
  if (entries.length === 0) return { todo: [], skipped: [] };
  const from = new Date(Math.min(...entries.map((e2) => e2.start.getTime())) - 6e4);
  const to = new Date(Math.max(...entries.map((e2) => e2.end.getTime())) + 6e4);
  const existing = await CalendarEvent.getAll(from, to);
  const todo = missingEntries(entries, existing.map((x) => ({ title: x.title, start: x.startDate.getTime() })));
  return { todo, skipped: entries.filter((e2) => !todo.includes(e2)) };
}
async function saveEntries(entries) {
  const calendar = await Calendar.defaultForEvents();
  if (!calendar) throw new Error("no default calendar");
  for (const e2 of entries) await newEvent(e2, calendar).save();
}

