var GROUP_PALETTE = [
  "#8E44AD",
  "#00A3A3",
  "#C9A100",
  "#D63384",
  "#5E5CE6",
  "#8B5E3C",
  "#6B8E23",
  "#17A2B8",
  "#7CB342",
  "#00695C",
  "#AD1457",
  "#B39DDB",
  "#FFB300",
  "#26C6DA",
  "#E91E63",
  "#3949AB",
  "#9E9D24",
  "#80CBC4",
  "#F48FB1",
  "#A1887F",
  "#AED581",
  "#4DB6AC",
  "#BA68C8",
  "#FFD54F",
  "#7986CB",
  "#55AAFF",
  "#FF55BB"
];
var FIXED_MAP_COLOURS = ["#007AFF", "#8E8E93"];
var MIN_COLOUR_DISTANCE = 0.1;
function oklab(hex) {
  const m = /^#([0-9A-Fa-f]{2})([0-9A-Fa-f]{2})([0-9A-Fa-f]{2})$/.exec(hex.trim());
  if (!m) return void 0;
  const [r, g, b] = [m[1], m[2], m[3]].map((h) => {
    const c = parseInt(h, 16) / 255;
    return c <= 0.04045 ? c / 12.92 : ((c + 0.055) / 1.055) ** 2.4;
  });
  const l = Math.cbrt(0.4122214708 * r + 0.5363325363 * g + 0.0514459929 * b);
  const mm = Math.cbrt(0.2119034982 * r + 0.6806995451 * g + 0.1073969566 * b);
  const s = Math.cbrt(0.0883024619 * r + 0.2817188376 * g + 0.6299787005 * b);
  return [
    0.2104542553 * l + 0.793617785 * mm - 0.0040720468 * s,
    1.9779984951 * l - 2.428592205 * mm + 0.4505937099 * s,
    0.0259040371 * l + 0.7827717662 * mm - 0.808675766 * s
  ];
}
function colourDistance(a, b) {
  const x = oklab(a), y = oklab(b);
  if (!x || !y) return Infinity;
  return Math.hypot(x[0] - y[0], x[1] - y[1], x[2] - y[2]);
}
function groupColors(groups, avoid) {
  const out = {};
  const taken = [];
  for (const g of groups) {
    const used = [...avoid, ...taken];
    const nearest = (c) => Math.min(Infinity, ...used.map((u) => colourDistance(c, u)));
    const free = GROUP_PALETTE.filter((c) => !taken.includes(c));
    const pool = free.length > 0 ? free : GROUP_PALETTE;
    const pick = pool.find((c) => nearest(c) >= MIN_COLOUR_DISTANCE) ?? pool.reduce((best, c) => nearest(c) > nearest(best) ? c : best, pool[0]);
    out[g] = pick;
    taken.push(pick);
  }
  return out;
}

